package mrpapermoon.whisper.mesh.dbimport androidx.room.Entityimport androidx.room.PrimaryKeyimport kotlinx.serialization.InternalSerializationApiimport kotlinx.serialization.Serializable@InternalSerializationApi @Serializable@Entity(tableName = "known_whisperers")data class WhispererEntity(	@PrimaryKey	val whispererId: String,	val decryptionKeys: Set<ByteArray>,	val karma: Int = 0,)